// DASHBOARD HOME
    private void showHome() {
            contentPanel.removeAll();
                    contentPanel.setLayout(new BorderLayout(10, 20));

                            JPanel top = new JPanel();
                                    top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
                                            top.setOpaque(false);

                                                    welcomeLabel = new JLabel("Welcome, " + userName + "!");
                                                            welcomeLabel.setFont(new Font("Inter", Font.BOLD, 28));

                                                                    JLabel description = new JLabel(
                                                                                "Track your fitness and achieve your goals."
                                                                                        );

                                                                                                top.add(welcomeLabel);
                                                                                                        top.add(Box.createVerticalStrut(8));
                                                                                                                top.add(description);

                                                                                                                        JPanel stats = new JPanel(new GridLayout(1, 3, 15, 15));
                                                                                                                                stats.setOpaque(false);

                                                                                                                                        stepsLabel = createStatCard("Daily Steps", steps + "");
                                                                                                                                                caloriesLabel = createStatCard("Calories Burned", calories + "");
                                                                                                                                                        workoutLabel = createStatCard(
                                                                                                                                                                    "Workouts Completed", workouts + ""
                                                                                                                                                                            );

                                                                                                                                                                                    stats.add(stepsLabel.getParent());
                                                                                                                                                                                            stats.add(caloriesLabel.getParent());
                                                                                                                                                                                                    stats.add(workoutLabel.getParent());

                                                                                                                                                                                                            JPanel center = new JPanel(new BorderLayout());
                                                                                                                                                                                                                    center.setOpaque(false);
                                                                                                                                                                                                                            center.add(stats, BorderLayout.NORTH);

                                                                                                                                                                                                                                    JPanel goal = new JPanel();
                                                                                                                                                                                                                                            goal.setLayout(new BoxLayout(goal, BoxLayout.Y_AXIS));
                                                                                                                                                                                                                                                    goal.setBackground(white);
                                                                                                                                                                                                                                                            goal.setBorder(new EmptyBorder(20, 20, 20, 20));

                                                                                                                                                                                                                                                                    JLabel goalTitle = new JLabel("Today's Fitness Goals");
                                                                                                                                                                                                                                                                            goalTitle.setFont(new Font("Inter", Font.BOLD, 20));

                                                                                                                                                                                                                                                                                    goal.add(goalTitle);
                                                                                                                                                                                                                                                                                            goal.add(Box.createVerticalStrut(15));
                                                                                                                                                                                                                                                                                                    goal.add(new JLabel("Daily Steps Goal: 10,000 steps"));
                                                                                                                                                                                                                                                                                                            goal.add(Box.createVerticalStrut(10));
                                                                                                                                                                                                                                                                                                                    goal.add(new JLabel("Stay hydrated and exercise daily!"));

                                                                                                                                                                                                                                                                                                                            center.add(goal, BorderLayout.CENTER);

                                                                                                                                                                                                                                                                                                                                    contentPanel.add(top, BorderLayout.NORTH);
                                                                                                                                                                                                                                                                                                                                            contentPanel.add(center, BorderLayout.CENTER);

                                                                                                                                                                                                                                                                                                                                                    applyTheme();
                                                                                                                                                                                                                                                                                                                                                            refreshScreen();
                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                    private JLabel createStatCard(String title, String value) {
                                                                                                                                                                                                                                                                                                                                                                            JPanel card = new JPanel();
                                                                                                                                                                                                                                                                                                                                                                                    card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
                                                                                                                                                                                                                                                                                                                                                                                            card.setBackground(white);
                                                                                                                                                                                                                                                                                                                                                                                                    card.setBorder(new EmptyBorder(20, 15, 20, 15));

                                                                                                                                                                                                                                                                                                                                                                                                            JLabel heading = new JLabel(title);
                                                                                                                                                                                                                                                                                                                                                                                                                    heading.setFont(new Font("Inter", Font.PLAIN, 14));

                                                                                                                                                                                                                                                                                                                                                                                                                            JLabel number = new JLabel(value);
                                                                                                                                                                                                                                                                                                                                                                                                                                    number.setFont(new Font("Inter", Font.BOLD, 25));
                                                                                                                                                                                                                                                                                                                                                                                                                                            number.setForeground(brand600);

                                                                                                                                                                                                                                                                                                                                                                                                                                                    card.add(heading);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            card.add(Box.createVerticalStrut(12));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    card.add(number);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }